import * as stylex from '@stylexjs/stylex';

// Both compilers refuse this, so the verdict is `both reject` -- which records
// that neither will compile it, and is the only verdict a refusal can earn here.
// Which position the refusal comes from, and what it says, is pinned in the Rust
// suite: the harness compares outcomes rather than messages, and a boolean is
// refused from four positions with two different messages between them.
export const styles = stylex.create({
  x: { color: false },
});

